-- HireFlow AI — initial schema.
-- Design: docs/architecture.md §7. Never edit this file once committed; add V2__..., V3__... instead.
--
-- Conventions
--   * uuid primary keys (generated by the application; the default is a fallback)
--   * timestamptz for every instant
--   * enums are varchar + CHECK, matching the Java enum names
--   * company_id on every company-owned table (tenant isolation, §5)
--   * composite foreign keys such as (job_id, company_id) make the DATABASE reject a row that
--     points at another company's record: a backstop under the service-layer checks.

CREATE EXTENSION IF NOT EXISTS vector;

-- ---------------------------------------------------------------------------
-- Companies and users
-- ---------------------------------------------------------------------------

CREATE TABLE companies (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        varchar(255) NOT NULL,
    email       varchar(255) NOT NULL,
    website     varchar(255),
    industry    varchar(100),
    description text,
    logo_url    text,
    address     text,
    status      varchar(30)  NOT NULL DEFAULT 'ACTIVE'
                CONSTRAINT chk_companies_status CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id    uuid REFERENCES companies (id),
    name          varchar(255) NOT NULL,
    email         varchar(255) NOT NULL,
    password_hash varchar(255),            -- null until an invite is accepted
    role          varchar(50)  NOT NULL
                  CONSTRAINT chk_users_role
                  CHECK (role IN ('SUPER_ADMIN', 'HR_ADMIN', 'RECRUITER', 'EMPLOYEE', 'CANDIDATE')),
    enabled       boolean      NOT NULL DEFAULT true,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT chk_users_email_lowercase CHECK (email = lower(email)),
    -- Super admins and candidates sit outside any company; everyone else must belong to one.
    CONSTRAINT chk_users_company_by_role
        CHECK ((role IN ('SUPER_ADMIN', 'CANDIDATE')) = (company_id IS NULL)),
    CONSTRAINT uq_users_id_company UNIQUE (id, company_id)
);
CREATE INDEX idx_users_company ON users (company_id);

CREATE TABLE refresh_tokens (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash  varchar(64) NOT NULL,      -- SHA-256 hex of the opaque token; the token itself is never stored
    family_id   uuid        NOT NULL,      -- all rotations of one login share a family (reuse detection)
    expires_at  timestamptz NOT NULL,
    revoked_at  timestamptz,
    replaced_by uuid REFERENCES refresh_tokens (id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_refresh_tokens_hash UNIQUE (token_hash)
);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX idx_refresh_tokens_family ON refresh_tokens (family_id);

CREATE TABLE password_reset_tokens (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash varchar(64) NOT NULL,
    purpose    varchar(20) NOT NULL
               CONSTRAINT chk_password_reset_tokens_purpose CHECK (purpose IN ('RESET', 'INVITE')),
    expires_at timestamptz NOT NULL,
    used_at    timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_password_reset_tokens_hash UNIQUE (token_hash)
);
CREATE INDEX idx_password_reset_tokens_user ON password_reset_tokens (user_id);

-- ---------------------------------------------------------------------------
-- Departments and employees (they reference each other: manager_id FK added below)
-- ---------------------------------------------------------------------------

CREATE TABLE departments (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id  uuid         NOT NULL REFERENCES companies (id),
    name        varchar(150) NOT NULL,
    description text,
    manager_id  uuid,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_departments_company_name UNIQUE (company_id, name),
    CONSTRAINT uq_departments_id_company UNIQUE (id, company_id)
);

CREATE TABLE employees (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id          uuid         NOT NULL REFERENCES companies (id),
    user_id             uuid         NOT NULL,
    department_id       uuid,
    employee_code       varchar(50)  NOT NULL,
    designation         varchar(150),
    joining_date        date,
    employment_status   varchar(30)  NOT NULL DEFAULT 'ACTIVE'
                        CONSTRAINT chk_employees_status CHECK (employment_status IN ('ACTIVE', 'INACTIVE')),
    phone               varchar(30),
    profile_picture_url text,
    created_at          timestamptz  NOT NULL DEFAULT now(),
    updated_at          timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_employees_user UNIQUE (user_id),
    CONSTRAINT uq_employees_company_code UNIQUE (company_id, employee_code),
    CONSTRAINT uq_employees_id_company UNIQUE (id, company_id),
    CONSTRAINT fk_employees_user_same_company
        FOREIGN KEY (user_id, company_id) REFERENCES users (id, company_id),
    -- No ON DELETE: deleting a department with employees is refused (409/422 at the service level).
    CONSTRAINT fk_employees_department_same_company
        FOREIGN KEY (department_id, company_id) REFERENCES departments (id, company_id)
);
CREATE INDEX idx_employees_company_department ON employees (company_id, department_id);

ALTER TABLE departments
    ADD CONSTRAINT fk_departments_manager_same_company
        FOREIGN KEY (manager_id, company_id) REFERENCES employees (id, company_id);

-- ---------------------------------------------------------------------------
-- Candidates and resumes (candidates are global; companies see them only through applications)
-- ---------------------------------------------------------------------------

CREATE TABLE candidates (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         uuid REFERENCES users (id),   -- null for recruiter-sourced candidates
    name            varchar(255) NOT NULL,
    email           varchar(255) NOT NULL,
    phone           varchar(30),
    location        varchar(255),
    profile_summary text,
    created_at      timestamptz  NOT NULL DEFAULT now(),
    updated_at      timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_candidates_user UNIQUE (user_id),
    CONSTRAINT uq_candidates_email UNIQUE (email),
    CONSTRAINT chk_candidates_email_lowercase CHECK (email = lower(email))
);

CREATE TABLE resumes (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    candidate_id   uuid         NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
    file_name      varchar(255) NOT NULL,          -- sanitised original name, metadata only
    storage_key    text         NOT NULL,          -- e.g. resumes/{uuid}.pdf
    content_type   varchar(100) NOT NULL,
    size_bytes     bigint       NOT NULL CONSTRAINT chk_resumes_size CHECK (size_bytes > 0),
    content_hash   varchar(64)  NOT NULL,          -- SHA-256 hex, detects duplicate uploads
    extracted_text text,
    text_status    varchar(20)  NOT NULL
                   CONSTRAINT chk_resumes_text_status CHECK (text_status IN ('EXTRACTED', 'EMPTY', 'FAILED')),
    parsed_data    jsonb,                          -- cached, validated LLM extraction (§8.3)
    parsed_at      timestamptz,
    created_at     timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_resumes_storage_key UNIQUE (storage_key),
    CONSTRAINT uq_resumes_candidate_hash UNIQUE (candidate_id, content_hash),
    CONSTRAINT uq_resumes_id_candidate UNIQUE (id, candidate_id)
);

-- ---------------------------------------------------------------------------
-- Jobs and applications
-- ---------------------------------------------------------------------------

CREATE TABLE jobs (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id       uuid          NOT NULL REFERENCES companies (id),
    created_by       uuid,
    title            varchar(255)  NOT NULL,
    description      text          NOT NULL,
    required_skills  jsonb         NOT NULL DEFAULT '[]'::jsonb,
    preferred_skills jsonb         NOT NULL DEFAULT '[]'::jsonb,
    min_experience   integer CONSTRAINT chk_jobs_min_experience CHECK (min_experience >= 0),
    max_experience   integer,
    employment_type  varchar(50)   NOT NULL
                     CONSTRAINT chk_jobs_employment_type
                     CHECK (employment_type IN ('FULL_TIME', 'PART_TIME', 'CONTRACT', 'INTERNSHIP')),
    location         varchar(255),
    salary_min       numeric(12, 2) CONSTRAINT chk_jobs_salary_min CHECK (salary_min >= 0),
    salary_max       numeric(12, 2),
    status           varchar(30)   NOT NULL DEFAULT 'DRAFT'
                     CONSTRAINT chk_jobs_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'CLOSED')),
    published_at     timestamptz,
    created_at       timestamptz   NOT NULL DEFAULT now(),
    updated_at       timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT chk_jobs_experience_range CHECK (max_experience IS NULL OR min_experience IS NULL
                                                OR max_experience >= min_experience),
    CONSTRAINT chk_jobs_salary_range CHECK (salary_max IS NULL OR salary_min IS NULL OR salary_max >= salary_min),
    CONSTRAINT chk_jobs_skills_are_arrays CHECK (jsonb_typeof(required_skills) = 'array'
                                                 AND jsonb_typeof(preferred_skills) = 'array'),
    CONSTRAINT uq_jobs_id_company UNIQUE (id, company_id),
    CONSTRAINT fk_jobs_created_by_same_company
        FOREIGN KEY (created_by, company_id) REFERENCES users (id, company_id)
);
CREATE INDEX idx_jobs_company_status ON jobs (company_id, status);
CREATE INDEX idx_jobs_published ON jobs (published_at DESC) WHERE status = 'PUBLISHED';

CREATE TABLE applications (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id   uuid        NOT NULL REFERENCES companies (id),
    job_id       uuid        NOT NULL,
    candidate_id uuid        NOT NULL REFERENCES candidates (id),
    resume_id    uuid        NOT NULL,
    status       varchar(50) NOT NULL DEFAULT 'APPLIED'
                 CONSTRAINT chk_applications_status
                 CHECK (status IN ('APPLIED', 'SCREENING', 'SHORTLISTED', 'INTERVIEW_SCHEDULED',
                                   'SELECTED', 'REJECTED')),
    source       varchar(20) NOT NULL DEFAULT 'CANDIDATE'
                 CONSTRAINT chk_applications_source CHECK (source IN ('CANDIDATE', 'RECRUITER')),
    applied_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_applications_job_candidate UNIQUE (job_id, candidate_id),
    CONSTRAINT uq_applications_id_company UNIQUE (id, company_id),
    CONSTRAINT fk_applications_job_same_company
        FOREIGN KEY (job_id, company_id) REFERENCES jobs (id, company_id),
    -- The attached resume must belong to the applying candidate.
    CONSTRAINT fk_applications_resume_of_candidate
        FOREIGN KEY (resume_id, candidate_id) REFERENCES resumes (id, candidate_id)
);
CREATE INDEX idx_applications_job_status ON applications (job_id, status);
CREATE INDEX idx_applications_company_status ON applications (company_id, status);
CREATE INDEX idx_applications_candidate ON applications (candidate_id);

CREATE TABLE application_status_history (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id uuid        NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    old_status     varchar(50),                 -- null for the initial APPLIED entry
    new_status     varchar(50) NOT NULL,
    changed_by     uuid REFERENCES users (id),
    reason         varchar(500),
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_application_status_history_application
    ON application_status_history (application_id, created_at);

CREATE TABLE application_notes (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    application_id uuid        NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    author_id      uuid        NOT NULL REFERENCES users (id),
    body           text        NOT NULL CONSTRAINT chk_application_notes_length CHECK (char_length(body) <= 5000),
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_application_notes_application ON application_notes (application_id, created_at);

-- ---------------------------------------------------------------------------
-- AI: screenings and embeddings (§8)
-- ---------------------------------------------------------------------------

CREATE TABLE ai_screenings (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id      uuid        NOT NULL REFERENCES companies (id),
    application_id  uuid        NOT NULL,
    status          varchar(30) NOT NULL DEFAULT 'PENDING'
                    CONSTRAINT chk_ai_screenings_status CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED')),
    match_score     numeric(5, 2)
                    CONSTRAINT chk_ai_screenings_score CHECK (match_score BETWEEN 0 AND 100),
    score_breakdown jsonb,
    matched_skills  jsonb,
    missing_skills  jsonb,
    explanation     text,
    model_name      varchar(150),
    prompt_version  varchar(50),
    error_message   text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    completed_at    timestamptz,
    CONSTRAINT fk_ai_screenings_application_same_company
        FOREIGN KEY (application_id, company_id) REFERENCES applications (id, company_id) ON DELETE CASCADE
);
CREATE INDEX idx_ai_screenings_application ON ai_screenings (application_id, created_at DESC);

-- One row per resume chunk PER COMPANY: the same resume applied to two companies is indexed
-- twice, so semantic search is a plain "WHERE company_id = ?" (§8.5).
-- 768 = gemini-embedding-001 with output dimensions set to 768 (§8.2).
CREATE TABLE resume_embeddings (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id   uuid         NOT NULL REFERENCES companies (id) ON DELETE CASCADE,
    resume_id    uuid         NOT NULL REFERENCES resumes (id) ON DELETE CASCADE,
    candidate_id uuid         NOT NULL REFERENCES candidates (id) ON DELETE CASCADE,
    chunk_index  integer      NOT NULL CONSTRAINT chk_resume_embeddings_chunk CHECK (chunk_index >= 0),
    content      text         NOT NULL,
    embedding    vector(768)  NOT NULL,
    created_at   timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_resume_embeddings_chunk UNIQUE (company_id, resume_id, chunk_index)
);
CREATE INDEX idx_resume_embeddings_company ON resume_embeddings (company_id);

-- ---------------------------------------------------------------------------
-- Interviews
-- ---------------------------------------------------------------------------

CREATE TABLE interviews (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id       uuid        NOT NULL REFERENCES companies (id),
    application_id   uuid        NOT NULL,
    interviewer_id   uuid        NOT NULL,
    scheduled_at     timestamptz NOT NULL,
    duration_minutes integer     NOT NULL DEFAULT 60
                     CONSTRAINT chk_interviews_duration CHECK (duration_minutes BETWEEN 5 AND 480),
    interview_type   varchar(50) NOT NULL
                     CONSTRAINT chk_interviews_type CHECK (interview_type IN ('PHONE', 'VIDEO', 'IN_PERSON')),
    meeting_link     text,
    instructions     text,
    status           varchar(30) NOT NULL DEFAULT 'SCHEDULED'
                     CONSTRAINT chk_interviews_status
                     CHECK (status IN ('SCHEDULED', 'COMPLETED', 'CANCELLED', 'NO_SHOW')),
    feedback         text,
    rating           smallint CONSTRAINT chk_interviews_rating CHECK (rating BETWEEN 1 AND 5),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fk_interviews_application_same_company
        FOREIGN KEY (application_id, company_id) REFERENCES applications (id, company_id),
    CONSTRAINT fk_interviews_interviewer_same_company
        FOREIGN KEY (interviewer_id, company_id) REFERENCES users (id, company_id)
);
CREATE INDEX idx_interviews_company_scheduled ON interviews (company_id, scheduled_at);
CREATE INDEX idx_interviews_interviewer_scheduled ON interviews (interviewer_id, scheduled_at);
CREATE INDEX idx_interviews_application ON interviews (application_id);

CREATE TABLE interview_questions (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    interview_id uuid        NOT NULL REFERENCES interviews (id) ON DELETE CASCADE,
    category     varchar(30) NOT NULL
                 CONSTRAINT chk_interview_questions_category
                 CHECK (category IN ('TECHNICAL', 'SCENARIO', 'PROBLEM_SOLVING')),
    question     text        NOT NULL
                 CONSTRAINT chk_interview_questions_length CHECK (char_length(question) <= 2000),
    source       varchar(20) NOT NULL
                 CONSTRAINT chk_interview_questions_source CHECK (source IN ('AI', 'MANUAL')),
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_interview_questions_interview ON interview_questions (interview_id);

-- ---------------------------------------------------------------------------
-- Notifications and audit
-- ---------------------------------------------------------------------------

CREATE TABLE notifications (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    type       varchar(50) NOT NULL,
    message    text        NOT NULL,
    link       text,
    read_at    timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_notifications_user_unread ON notifications (user_id, created_at DESC) WHERE read_at IS NULL;

CREATE TABLE audit_logs (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id  uuid REFERENCES companies (id),      -- null for platform-level actions
    user_id     uuid REFERENCES users (id) ON DELETE SET NULL,
    action      varchar(100) NOT NULL,
    entity_type varchar(100),
    entity_id   uuid,
    details     jsonb,
    created_at  timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_logs_company_created ON audit_logs (company_id, created_at DESC);
